R=Path(__file__).parent; SITE='https://topshelfagency.biz'; EMAIL='hello@topshelfagency.biz'
NAV='''<header class="nav" id="siteNav"><div class="wrap nav-row"><a class="brand" href="/"><img src="/assets/logo/logo-mark.svg" width="32" height="32" alt=""><span>TOP SHELF <b>AGENCY</b></span></a><nav aria-label="Primary"><div class="nav-links"><a href="/growth-package/">Growth Package</a><a href="/growth-audit/">Free Growth Audit</a><a href="/how-it-works/">How It Works</a><a href="/about/">About</a><a href="/faq/">FAQ</a><a class="btn" data-event="audit_cta_click" href="/growth-audit/">Get My Free Growth Audit</a><button id="navToggle" aria-expanded="false" aria-controls="mobileMenu">Menu</button></div></nav></div><nav id="mobileMenu" class="mobile-menu"><a href="/growth-package/">Growth Package</a><a href="/growth-audit/">Free Growth Audit</a><a href="/how-it-works/">How It Works</a><a href="/about/">About</a><a href="/faq/">FAQ</a><a href="/contact/">Contact</a></nav></header>'''
