def data(kind='ProfessionalService',extra=None):
 d={'@context':'https://schema.org','@type':kind,'name':'Top Shelf Agency LLC','url':SITE,'email':EMAIL,'areaServed':'Northern New Jersey'}; d.update(extra or {}); return d
def write(path,title,desc,body,structured=None,noindex=False):
 p=R/path;p.parent.mkdir(parents=True,exist_ok=True);url='/' if path=='index.html' else '/'+path.replace('index.html','')
 p.write_text(f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{title}</title><meta name="description" content="{desc}">{'<meta name="robots" content="noindex,follow">' if noindex else ''}<link rel="canonical" href="{SITE+url}"><link rel="icon" href="/favicon.ico"><link rel="stylesheet" href="/assets/site.css"><meta property="og:type" content="website"><meta property="og:title" content="{title}"><meta property="og:description" content="{desc}"><meta property="og:url" content="{SITE+url}"><meta property="og:image" content="{SITE}/assets/logo/og-image-1200x630.png"><meta name="twitter:card" content="summary_large_image"><script type="application/ld+json">{json.dumps(structured or data())}</script><script src="/assets/config.js"></script></head><body><a class="skip" href="#main">Skip to content</a>{NAV}<main id="main">{body}</main>{FOOT}<script src="/assets/site.js"></script></body></html>''',encoding='utf-8')
def ph(e,h,l):return f'<section class="page-head"><div class="wrap"><p class="eyebrow">{e}</p><h1>{h}</h1><p class="lede">{l}</p></div></section>'
def cta():return '<section class="final"><div class="wrap"><p class="eyebrow">A practical first step</p><h2>Find the opportunities your business may be missing.</h2><p>Get a Growth Audit focused on revenue, customer experience, and owner time. No generic pitch and no recommendation before we confirm what is already in place.</p><a class="btn" data-event="audit_cta_click" href="/growth-audit/">Get My Free Growth Audit</a></div></section>'
P=[('01','Capture missed opportunities','Missed-call text-back and simple forms can keep a homeowner request alive while you are on a job.'),('02','Follow up faster','Thoughtful email and text follow-up can help estimates and inquiries get a timely next step.'),('03','Generate legitimate reviews','Make it easier to ask real customers for honest feedback after completed work.'),('04','Keep leads organized','Keep conversations, estimates, appointments, and next steps in one place.')]
cards=lambda tag='h3':''.join(f'<article><span>{n}</span><{tag}>{h}</{tag}><p>{x}</p></article>' for n,h,x in P)
home='''<section class="hero"><div class="wrap split"><div><p class="eyebrow">For North Jersey Plumbing and Electrical Companies</p><h1>Stop losing good jobs when you are too busy to answer the phone.</h1><p class="lede">Top Shelf helps small contractors capture missed opportunities, follow up faster, earn more legitimate reviews, and keep every lead organized without adding more work to the owner's day.</p><div class="actions"><a class="btn" href="/growth-audit/">Get My Free Growth Audit</a><a href="/how-it-works/">See How It Works →</a></div><p class="trust">Built for small local contractors. Based in North Jersey. Personal support from the founder.</p></div><aside class="ticket"><small>Tuesday · 2:18 PM</small><h2>You are under a sink.<br>The next job is calling.</h2><p>Missed call → Helpful text → Lead saved</p><small>A process example—not a client result.</small></aside></div></section><section><div class="wrap"><p class="eyebrow">Where good jobs slip away</p><h2>Good work is not the problem. Missed opportunities are.</h2><div class="grid four"><article><span>01</span><h3>The phone rings mid-job</h3><p>A homeowner reaches voicemail while the owner is working.</p></article><article><span>02</span><h3>An estimate waits</h3><p>A promising request sits too long without a clear next step.</p></article><article><span>03</span><h3>The review ask gets missed</h3><p>A satisfied customer is never asked for an honest review.</p></article><article><span>04</span><h3>A lead disappears</h3><p>A name lives in texts, paper, or memory and gets no follow-up.</p></article></div></div></section><section class="surface"><div class="wrap"><p class="eyebrow">The Contractor Growth Package</p><h2>One practical growth system built around how your company already works.</h2><div class="grid four">'''+cards()+'''</div><p class="note"><b>We verify what you already have before recommending changes.</b> If a system is working, we work with it rather than replacing it without a reason.</p><a href="/growth-package/">Explore the Growth Package →</a></div></section><section><div class="wrap split"><div><p class="eyebrow">Free Business Growth Audit</p><h2>Start with the customer journey, not a sales pitch.</h2><p>The audit reviews missed calls, response speed, lead capture, estimate follow-up, review generation, online visibility, and owner communication bottlenecks.</p><a class="btn" href="/growth-audit/">Get My Free Growth Audit</a></div><div class="stack"><p><b>It is not</b> a cosmetic critique.</p><p><b>We verify first.</b> Public observations are confirmed before becoming gaps.</p><p><b>Recommendations stay practical.</b> Every suggestion needs a believable business connection.</p></div></div></section><section class="surface"><div class="wrap"><p class="eyebrow">How it works</p><h2>A clear process with approval at every important step.</h2><div class="grid four"><article><b>01</b><h3>Audit</h3><p>Review and confirm what exists.</p></article><article><b>02</b><h3>Plan</h3><p>Identify the highest-value improvement.</p></article><article><b>03</b><h3>Build and test</h3><p>Configure and test with the owner.</p></article><article><b>04</b><h3>Launch and improve</h3><p>Go live only after approval.</p></article></div></div></section><section><div class="wrap split"><div><p class="eyebrow">Founder-led in North Jersey</p><h2>Personal accountability, not a handoff maze.</h2><p>Steve Wierzbicki, Founder, stays involved in the problem, recommendation, and testing. Every recommendation should still feel honest if we run into each other around town.</p><a href="/about/">About Steve and Top Shelf →</a></div><div class="placeholder"><b>Founder photography pending</b><p>A real, approved photo belongs here.</p></div></div></section><section class="surface"><div class="wrap"><p class="eyebrow">Fit matters</p><h2>Who Top Shelf is built for</h2><div class="grid two"><article><h3>A strong fit</h3><ul><li>North Jersey plumber or electrician</li><li>Usually 1 to 5 employees</li><li>Owner often works in the field</li><li>Capacity for profitable work</li><li>Willing to verify and test</li></ul></article><article><h3>Probably not a fit</h3><ul><li>Looking for miracles or guarantees</li><li>No capacity or margin</li><li>Sophisticated follow-up already exists</li><li>Cannot participate in testing</li></ul></article></div></div></section><section><div class="wrap"><p class="eyebrow">Process proof, not invented results</p><h2>What gets tested before launch</h2><div class="grid three"><article><b>Missed call</b><p>Approved response and reply routing.</p></article><article><b>Lead record</b><p>Answers and attribution without duplicates.</p></article><article><b>Owner handoff</b><p>Notifications, tasks, appointments, and stop conditions.</p></article></div><small>Demonstration checklist. It does not represent client performance.</small></div></section>'''+cta()
write('index.html','Contractor Lead Follow-Up in North Jersey | Top Shelf Agency','Top Shelf helps North Jersey plumbers and electricians capture missed opportunities, follow up faster, earn legitimate reviews, and organize leads.',home)
package=ph('Top Shelf Contractor Growth Package','One connected system for the moments where good jobs get lost.','Built for small North Jersey plumbing and electrical companies that need a dependable customer journey.')+f'<section><div class="wrap"><div class="grid four">{cards("h2")}</div><div class="prose"><h2>Capabilities support the outcome</h2><p>Depending on what the audit confirms, the package may use missed-call text-back, forms, booking, follow-up, review requests, pipeline management, and reporting inside GoHighLevel. These are components—not separate products.</p><h2>We work with what is working</h2><p>This may already be handled internally. Nothing goes live before testing and owner approval.</p><h2>No invented promise</h2><p>Scope and timing depend on needs, access, integrations, compliance review, and testing. Pricing is not published until finalized.</p></div></div></section>'+cta();write('growth-package/index.html','Contractor Growth Package | Top Shelf Agency','A practical contractor system for missed opportunities, follow-up, reviews, and organized leads.',package,data('Service',{'serviceType':'Top Shelf Contractor Growth Package'}))
FORM='''<form id="growthAuditForm" class="form" novalidate><div id="formStatus" class="status" role="status" aria-live="polite"></div><div class="hp"><label>Leave blank<input name="company_fax" tabindex="-1"></label></div><div class="fields"><label>Full name *<input name="full_name" autocomplete="name" required></label><label>Business name *<input name="business_name" autocomplete="organization" required></label><label>Phone *<input name="phone" type="tel" autocomplete="tel" required></label><label>Email *<input name="email" type="email" autocomplete="email" required></label><label>Website (optional)<input name="website" type="url" placeholder="https://"></label><label>Business town *<input name="business_town" required></label><label>Trade *<select name="trade" required><option value="">Choose one</option><option>Plumbing</option><option>Electrical</option><option>Other</option></select></label><label>Team size *<select name="team_size" required><option value="">Choose one</option><option>1</option><option>2–5</option><option>6–10</option><option>11+</option></select></label><label class="wide">Best time to contact *<input name="best_time" required></label><label class="wide">Biggest growth or follow-up concern *<textarea name="concern" rows="5" required></textarea></label></div><input type="hidden" name="utm_source"><input type="hidden" name="utm_medium"><input type="hidden" name="utm_campaign"><input type="hidden" name="utm_content"><input type="hidden" name="utm_term"><input type="hidden" name="landing_page"><input type="hidden" name="first_touch_url"><label class="consent"><input name="consent" type="checkbox" required><span id="consentCopy">I agree that Top Shelf Agency LLC may contact me about my Growth Audit by phone, email, and text. Message and data rates may apply. Consent is not a condition of purchase. Reply STOP to opt out.</span></label><button class="btn" type="submit">Get My Free Growth Audit</button><small>See our <a href="/privacy/">Privacy Policy</a>.</small></form>'''
audit=ph('Free Business Growth Audit','Find the follow-up opportunities worth fixing first.','A practical review focused on revenue, customer experience, and owner time.')+'''<section><div class="wrap audit"><div><h2>What it covers</h2><ul><li>Missed calls and response speed</li><li>Lead capture and follow-up</li><li>Estimates and booking</li><li>Legitimate reviews</li><li>Online visibility tied to acquisition</li><li>Owner communication bottlenecks</li></ul><h2>What it does not cover</h2><p>This is not a cosmetic critique. Public observations become questions and are confirmed before being treated as gaps.</p><h2>What you receive</h2><p>Steve verifies the journey and explains the highest-value practical opportunity he can support. Do not include passwords or customer information.</p></div>'''+FORM+'</div></section>';write('growth-audit/index.html','Free Business Growth Audit for North Jersey Contractors | Top Shelf Agency','Request a free practical Growth Audit for your North Jersey plumbing or electrical company.',audit)
process=ph('How it works','Confirm first. Build only what earns its place.','The process protects the customer experience and keeps the owner in control.')+'''<section><div class="wrap grid four"><article><b>01</b><h2>Audit</h2><p>Review and confirm what exists.</p></article><article><b>02</b><h2>Plan</h2><p>Identify value and agree on scope.</p></article><article><b>03</b><h2>Build and test</h2><p>Test messages, routing, records, tasks, attribution, and stop conditions.</p></article><article><b>04</b><h2>Launch and improve</h2><p>Go live after approval, then review real conversations.</p></article></div></section>'''+cta();write('how-it-works/index.html','How Contractor Growth Systems Work | Top Shelf Agency','How Top Shelf audits, plans, builds, tests, and improves contractor follow-up.',process)
about=ph('About Steve and Top Shelf','Local work deserves local accountability.','Top Shelf helps small North Jersey contractors improve the moments between an inquiry and the next step.')+'''<section><div class="wrap split"><div class="prose"><h2>Founder-led from the first conversation</h2><p>Steve Wierzbicki, Founder, is involved in the audit, recommendation, and testing. The goal is a verified business improvement, not technology for its own sake.</p><h2>The neighbor test</h2><p>Confirm what works, explain tradeoffs plainly, and never invent urgency, results, or guarantees.</p><h2>Built around your operation</h2><p>GoHighLevel stays behind the scenes as the delivery platform; it is not custom software.</p></div><div class="placeholder"><b>Founder photography pending</b><p>A real, approved photograph is required here.</p></div></div></section>'''+cta();write('about/index.html','About Steve Wierzbicki and Top Shelf Agency','Meet Steve Wierzbicki, Founder of Top Shelf Agency in North Jersey.',about)
